from io import StringIO

from ..data_object import DataObject
from mudlab.generic.utils import not_none

class XRDDataObject(DataObject):
    """
        A generic class holding all the information retrieved from an XRD data
        file using an XRD-parser class.
    """

    # General information
    name = None
    date = None

    # x-axis range
    twotheta_min = None
    twotheta_max = None
    twotheta_count = None
    twotheta_step = None

    # Wavelength and target information
    target_type = None
    alpha1 = None
    alpha2 = None
    alpha_average = None
    beta = None
    alpha_factor = None

    # Goniometer setup
    radius = None
    soller1 = None
    soller2 = None
    divergence = None

    # Acquisition
    count_time = None

    # Generator or list of x,y data
    data = None

    def get_goniometer_wavelength(self):
        """
        The single wavelength (in nm) the goniometer should use.

        Prefer Kα1 (``self.alpha1``) — the conventional XRD wavelength and the
        value MudLab's own default goniometers use (Cu Kα1 = 0.154056 nm).
        Diffraction software quotes and uses Kα1, *not* the Kα1/Kα2 weighted
        average; the Kα2 contribution is handled separately by the wavelength
        distribution. PANalytical XRDML scans confirm this with
        ``<usedWavelength intended="K-Alpha 1">``. Fall back to the parsed
        average, then the Cu Kα1 default. A non-positive value is treated as
        absent (it would otherwise make range_stl divide by zero).
        """
        for wl in (self.alpha1, self.alpha_average):
            if wl and wl > 0:
                return float(wl)
        return 0.154056

    def create_gon_file(self):

        output = """        {
            "type": "Goniometer", 
            "properties": {
                "radius": %(radius)f, 
                "divergence": %(divergence)f, 
                "soller1": %(soller1)f, 
                "soller2": %(soller2)f, 
                "min_2theta": %(twotheta_min)f, 
                "max_2theta": %(twotheta_max)f, 
                "steps": %(twotheta_count)f,
                "wavelength": %(wavelength)f,
                "has_ads": false,
                "ads_fact": 1.0, 
                "ads_phase_fact": 1.0, 
                "ads_phase_shift": 0.0, 
                "ads_const": 0.0
            }
        }""" % dict(
            # Radius and divergence are divisors in the auto-divergence-slit
            # correction (sample_length / (radius * tan(divergence))); a 0 from
            # the file would divide by zero, so fall back to defaults.
            radius=(float(self.radius) if self.radius and self.radius > 0 else 25),
            divergence=(float(self.divergence)
                        if self.divergence and self.divergence > 0 else 0.5),
            soller1=float(not_none(self.soller1, 2.5)),
            soller2=float(not_none(self.soller2, 2.5)),
            twotheta_min=float(not_none(self.twotheta_min, 3.0)),
            twotheta_max=float(not_none(self.twotheta_max, 45.0)),
            twotheta_count=float(not_none(self.twotheta_count, 2500)),
            # Kα1-preferred, zero-guarded (see get_goniometer_wavelength).
            wavelength=self.get_goniometer_wavelength(),
        )
        f = StringIO(output)
        f.flush()
        return f


    pass #end of class
